const setCalendarRange = `-- name: SetCalendarRange :execrows
INSERT INTO availability_calendar (listing_id, day, status, source, ref_id, updated_at)
SELECT $1::uuid, d::date, $2::text, $3::text, $4::uuid, $5::timestamptz
  FROM generate_series($6::date, $7::date, interval '1 day') AS d
ON CONFLICT (listing_id, day) DO UPDATE SET status = EXCLUDED.status, source = EXCLUDED.source, ref_id = EXCLUDED.ref_id, updated_at = EXCLUDED.updated_at
 WHERE availability_calendar.status = 'AVAILABLE'
    OR (EXCLUDED.source = 'OWNER' AND availability_calendar.status = 'BLOCKED' AND availability_calendar.source IN ('OWNER','EXTERNAL'))
    OR (EXCLUDED.ref_id IS NOT NULL AND availability_calendar.ref_id = EXCLUDED.ref_id)
`

type SetCalendarRangeParams struct {
	ListingID ids.ID
	Status    string
	Source    string
	RefID     *ids.ID
	Now       time.Time
	FromDay   time.Time
	ToDay     time.Time
}

func (q *Queries) SetCalendarRange(ctx context.Context, db DBTX, arg SetCalendarRangeParams) (int64, error) {
	result, err := db.Exec(ctx, setCalendarRange,
		arg.ListingID,
		arg.Status,
		arg.Source,
		arg.RefID,
		arg.Now,
		arg.FromDay,
		arg.ToDay,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

