const settingsWithExternalCalendar = `-- name: SettingsWithExternalCalendar :many
SELECT listing_id, property_id, max_guests, min_nights, max_nights, check_in_time, check_out_time, instant_book, guest_verification_required, payment_collection, cancellation_policy, house_rules, add_ons, turnover_buffer_days, damage_claim_window_hours, external_calendar_ref, version, created_at, updated_at FROM shortlet_settings WHERE external_calendar_ref IS NOT NULL ORDER BY updated_at LIMIT $1
`

func (q *Queries) SettingsWithExternalCalendar(ctx context.Context, db DBTX, limit int32) ([]ShortletSetting, error) {
	rows, err := db.Query(ctx, settingsWithExternalCalendar, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ShortletSetting
	for rows.Next() {
		var i ShortletSetting
		if err := rows.Scan(
			&i.ListingID,
			&i.PropertyID,
			&i.MaxGuests,
			&i.MinNights,
			&i.MaxNights,
			&i.CheckInTime,
			&i.CheckOutTime,
			&i.InstantBook,
			&i.GuestVerificationRequired,
			&i.PaymentCollection,
			&i.CancellationPolicy,
			&i.HouseRules,
			&i.AddOns,
			&i.TurnoverBufferDays,
			&i.DamageClaimWindowHours,
			&i.ExternalCalendarRef,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

